let data={profiles:[],items:[],cutoff:''}, current={type:'home'}, selectedPost=null, editingItem=null, editingProfile=null, chosenDestination=null, filter='all', sourceData=null, sourceTimer=null, sourcePage=0, sourceSearch='', previewObserver=null;
let timerInfo={schedules:[],batch:null}, sourceCounts=new Map(), selectedSchedule=null, selectedScheduleRole='source', previewUrls=[], activeVideo=null;
