function showLocation(location){if(['source','profile'].includes(location.type)&&!profileById(location.value))location={type:location.type==='source'?'sources':'home',value:null,categoryRole:location.type==='source'?'source':'destination'};LVLibrary.dispose();clearInterval(sourceTimer);sourceTimer=null;disposeGallery();sourceData=null;sourcePage=0;sourceSearch='';categoryRole=location.categoryRole;current={type:location.type,value:location.value};chosenDestination=null;filter='all';$('notice').textContent='';render();if(current.type==='source')loadSource(current.value);if(current.type==='profile')loadProfileDownloads(current.value);if(current.type==='sources'||current.type==='tag')loadSourceCounts();window.scrollTo(0,0);}
function go(type,value,role=categoryRole){const location={type,value:value??null,categoryRole:role},last=navigationHistory[navigationIndex];if(last.type!==location.type||last.value!==location.value||last.categoryRole!==location.categoryRole){navigationHistory=navigationHistory.slice(0,navigationIndex+1);navigationHistory.push(location);navigationIndex++;}showLocation(location);}
function moveHistory(delta){const next=navigationIndex+delta;if(next<0||next>=navigationHistory.length)return;navigationIndex=next;showLocation(navigationHistory[navigationIndex]);}
function avatar(p,large=false){const initial=esc((p.name||'?').replace(/^@/,'').slice(0,1).toUpperCase());const image=p.avatar_url?`<img src="${esc(p.avatar_url)}" alt="" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><b class="avatar-fallback" hidden>${initial}</b>`:initial;return `<div class="avatar ${esc(p.platform)} ${large?'large':''}">${image}<span>${esc(platformLabel(p.platform).slice(0,1))}</span></div>`;}
function categoryStyle(role,name){return (data.categories||[]).find(c=>c.role===role&&c.name.toLowerCase()===name.toLowerCase())||{};}
function categoryIcon(role,name,cls='category-avatar'){const c=categoryStyle(role,name),color=['pink','purple','blue','teal','green','yellow','orange','gray'].includes(c.color)?c.color:'pink';return `<span class="${cls} category-color-${color}">${c.image_url?`<img src="${esc(c.image_url)}" alt="">`:esc(c.icon||'#')}</span>`;}
function profileCard(p){return `<button class="profile-card source-account" data-profile="${p.id}" data-ring="${p.id}">${avatar(p,true)}<strong>@${esc(p.name)}</strong><div class="profile-sub">${esc(platformLabel(p.platform))}</div><div class="timer-label" data-timer="${p.id}">Auto sync off</div><div class="profile-tags">${p.tags.slice(0,2).map(t=>`<span>${esc(t)}</span>`).join('')}</div></button>`;}
