function renderNav(){document.querySelector('[data-home]').classList.toggle('active',current.type==='home'||current.type==='profile'||(current.type==='tag'&&categoryRole==='destination'));document.querySelector('[data-sources]').classList.toggle('active',current.type==='sources'||current.type==='source'||(current.type==='tag'&&categoryRole==='source'));}
