 $('view').innerHTML=`<div class="simple-heading"><div><div class="eyebrow">${isSources?'CONTENT DISCOVERY':'YOUR SPACE'}</div><h1>${isSources?'Sources':'Profiles'}<span>.</span></h1></div><div class="heading-actions"><span class="total-count">${p.length} ${label}</span>${isSources?'<button class="button outline" id="add-solo">＋ Post links</button><button class="button ghost" id="discover-sources">Find existing</button><button class="button outline" id="audit-all-dates">Audit dates</button><button class="button outline" id="source-config">⚙ Source folders</button><button class="button primary" id="sync-all">↻ Sync all</button>':''}</div></div>${isSources?'<div id="batch-status" class="batch-status" hidden></div>':''}<div class="section-heading workspace-heading"><div><div class="eyebrow">ORGANIZE YOUR ${label.toUpperCase()}</div><h2>Categories</h2></div><div class="heading-actions"><button class="button ghost" id="removed-accounts">Removed accounts</button><button class="button outline" id="new-category">＋ New category</button></div></div><div class="workspace-categories">${tags.map(t=>{const members=p.filter(x=>hasTag(x,t));return `<section class="workspace-category"><button class="workspace-category-open" data-tag="${esc(t)}">${categoryIcon(role,t,'workspace-category-icon')}<span class="workspace-category-text"><strong>${esc(t)}</strong><small>${members.length} ${members.length===1?(isSources?'source':'profile'):label}</small></span><span class="workspace-avatars">${members.slice(0,4).map(x=>avatar(x)).join('')}</span><span class="workspace-category-arrow">↗</span></button><button class="workspace-category-manage" data-manage="${esc(t)}" aria-label="Manage ${esc(t)} category">Manage</button></section>`;}).join('')||`<p class="workspace-empty">Create a category to group your ${label}.</p>`}</div><div class="section-heading workspace-heading"><div><div class="eyebrow">YOUR COLLECTION</div><h2>All ${label}</h2></div></div><div class="profiles-grid simple-grid">${p.map(isSources?sourceCard:profileCard).join('')}<button class="profile-card add-card" data-add><span>＋</span><strong>Add ${isSources?'source':'profile'}</strong></button></div>`;
 attachProfiles();updateTimerElements();document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openProfile(null,'',role));
