  $('view').innerHTML=`<div class="simple-heading"><div><div class="eyebrow">YOUR SPACE</div><h1>Categories<span>.</span></h1></div><button class="button primary" id="new-category">＋ New category</button></div><div class="category-tabs" role="tablist" aria-label="Category section"><button role="tab" aria-selected="${!isSources}" data-category-role="destination">Profiles</button><button role="tab" aria-selected="${isSources}" data-category-role="source">Sources</button></div><div class="category-section-heading"><div><h2>${isSources?'Source categories':'Profile categories'}</h2><p>Organize your ${label} into the groups you use.</p></div><span class="total-count">${tags.length} ${tags.length===1?'category':'categories'}</span></div><div class="category-grid">${tags.map(t=>{const members=data.profiles.filter(p=>p.role===categoryRole&&hasTag(p,t));return `<section class="category-card"><header><div><span class="category-icon">#</span><div><h2>${esc(t)}</h2><small>${members.length} ${isSources?(members.length===1?'source':'sources'):(members.length===1?'profile':'profiles')}</small></div></div><button class="category-open" data-tag="${esc(t)}">Dashboard ↗</button></header><div class="category-members">${members.map(quickProfile).join('')||`<p class="category-empty">No ${label} yet.</p>`}</div><div class="category-card-footer"><button class="category-manage" data-manage="${esc(t)}">＋ Manage ${label}</button></div></section>`;}).join('')}</div>${tags.length?'':`<div class="empty"><h3>No ${label} categories yet</h3><p>Create one to start organizing your ${label}.</p></div>`}`;
