function openQuickEditor(p,f){if(!p)return;quickEdit={p,f,result:null};$('quick-editor-title').textContent=f.title||f.name;$('editor-crop').value='original';$('editor-start').value=0;$('editor-end').value='';$('editor-mute').checked=false;$('editor-logo').value='';$('editor-caption').value=f.description||'';$('editor-error').textContent='';$('editor-status').textContent='';$('editor-download').hidden=true;$('editor-queue').disabled=true;const profiles=data.profiles.filter(x=>x.role==='destination');$('editor-target').innerHTML=profiles.map(x=>`<option value="${x.id}">${esc(platformLabel(x.platform))} · @${esc(x.name)}</option>`).join('');if(current.type==='profile'&&profiles.some(x=>x.id===current.value))$('editor-target').value=String(current.value);$('editor-target-label').hidden=p.role!=='source';$('editor-queue').hidden=p.role!=='source';$('editor-trim').hidden=f.kind!=='video';$('editor-mute').closest('label').hidden=f.kind!=='video';const src=p.role==='source'?`/api/sources/${p.id}/file?path=${encodeURIComponent(f.path)}`:`/api/profiles/${p.id}/download-file?path=${encodeURIComponent(f.path)}`;$('editor-preview').innerHTML=f.kind==='video'?`<video controls playsinline src="${esc(src)}"></video>`:`<img src="${esc(src)}" alt="Original media">`;$('editor-crop').onchange=()=>{const ratio=$('editor-crop').value;$('editor-preview').style.aspectRatio=ratio==='original'?'auto':ratio.replace(':',' / ');};$('editor-preview').style.aspectRatio='auto';$('quick-editor-dialog').showModal();}
['editor-crop','editor-start','editor-end','editor-mute','editor-logo'].forEach(id=>$(id).addEventListener('change',()=>{if(quickEdit?.result){quickEdit.result=null;$('editor-download').hidden=true;$('editor-queue').disabled=true;$('editor-status').textContent='Settings changed. Create a new edited copy.';}}));
$('quick-editor-dialog').addEventListener('close',()=>{const v=$('editor-preview').querySelector('video');if(v){v.pause();v.removeAttribute('src');v.load();}});
$('editor-render').onclick=async e=>{const button=e.currentTarget;if(!quickEdit)return;const start=Number($('editor-start').value||0),end=$('editor-end').value?Number($('editor-end').value):null;if(end!==null&&end<=start){$('editor-error').textContent='End time must be after start time.';return;}button.disabled=true;$('editor-queue').disabled=true;$('editor-download').hidden=true;$('editor-error').textContent='';$('editor-status').textContent='Rendering edited copy…';try{const form=new FormData();form.append('options',JSON.stringify({profile_id:quickEdit.p.id,role:quickEdit.p.role,path:quickEdit.f.path,crop:$('editor-crop').value,start,end,mute:$('editor-mute').checked}));if($('editor-logo').files[0])form.append('overlay',$('editor-logo').files[0]);const result=await api('/api/editor/render',{method:'POST',body:form});quickEdit.result=result;const file=result.role==='source'?`/api/sources/${result.profile_id}/file?path=${encodeURIComponent(result.path)}`:`/api/profiles/${result.profile_id}/download-file?path=${encodeURIComponent(result.path)}`;$('editor-download').href=file;$('editor-download').download='lifeinvader-edit'+(quickEdit.f.kind==='video'?'.mp4':'.jpg');$('editor-download').hidden=false;$('editor-queue').disabled=!$('editor-target').value;$('editor-preview').innerHTML=quickEdit.f.kind==='video'?`<video controls playsinline src="${esc(file)}"></video>`:`<img src="${esc(file)}" alt="Edited media">`;$('editor-preview').style.aspectRatio='auto';$('editor-status').textContent='Edited copy is ready to review or download.';}catch(err){$('editor-error').textContent=err.message;$('editor-status').textContent='';}finally{button.disabled=false;}};
$('editor-target').onchange=()=>{$('editor-queue').disabled=!quickEdit?.result||!$('editor-target').value;};
$('editor-queue').onclick=async e=>{const b=e.currentTarget;if(!quickEdit?.result)return;b.disabled=true;try{const target=Number($('editor-target').value);await api(`/api/profiles/${target}/queue`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_id:quickEdit.p.id,path:quickEdit.f.path,edit_id:quickEdit.result.id,caption:$('editor-caption').value})});$('editor-status').textContent='Added to the queue for review. Nothing has been posted.';if(current.type==='profile'&&current.value===target)loadQueue(target);}catch(err){$('editor-error').textContent=err.message;b.disabled=false;}};
let categoryAppearance=null;
function openCategoryAppearance(name,role){categoryAppearance={name,role};const c=categoryStyle(role,name);$('category-appearance-title').textContent=name;$('category-icon-select').value=c.icon||'#';$('category-color-select').value=c.color||'pink';$('category-photo').value='';$('category-clear-photo').checked=false;$('category-appearance-error').textContent='';function paint(){for(const [id,select] of [['category-icon-grid','category-icon-select'],['category-color-grid','category-color-select']]){$(id).innerHTML=[...$(select).options].map(o=>`<button type="button" class="category-choice ${id==='category-color-grid'?'category-color-'+esc(o.value):''}" data-choice="${esc(o.value)}" aria-pressed="${o.value===$(select).value}" title="${esc(o.text)}">${id==='category-icon-grid'?esc(o.value):'●'}</button>`).join('');$(id).querySelectorAll('button').forEach(b=>b.onclick=()=>{$(select).value=b.dataset.choice;if(id==='category-icon-grid')$('category-clear-photo').checked=true;paint();});}}$('category-icon-select').onchange=paint;$('category-color-select').onchange=paint;paint();$('category-appearance-dialog').showModal();}
