function stats(profiles,items){const dests=profiles.filter(p=>p.role==='destination');const states=items.flatMap(i=>dests.map(p=>status(i,p.id)).filter(Boolean));return `<div class="dashboard-stats"><div><small>LIBRARY ITEMS</small><strong>${items.length}</strong><span>Available in this view</span></div><div><small>AVAILABLE</small><strong>${states.filter(s=>s.state==='available').length}</strong><span>Across posting accounts</span></div><div><small>CLAIMED</small><strong>${states.filter(s=>s.state==='claimed').length}</strong><span>Currently in progress</span></div><div><small>REPORTED POSTED</small><strong>${states.filter(s=>s.state==='reported_posted').length}</strong><span>Manually recorded</span></div></div>`;}
