document.querySelector('[data-crumb]').onclick=()=>go(p?'home':'categories');attachProfiles();if(p)$('edit-profile').onclick=()=>openProfile(p);else {$('manage-category').onclick=()=>openMembers(current.value,'destination');$('add-from-category').onclick=()=>openProfile(null,current.value);if($('sync-category'))$('sync-category').onclick=()=>syncAll(group.filter(x=>x.role==='source'));}updateTimerElements();
