function fileDate(f){
  let date,label;
  if(f.posted_date){date=new Date(f.posted_date+'T12:00:00');label=f.posted_date_kind==='estimated_id'?'Estimated post date (UTC)':'Posted';}
  else if(f.downloaded_at){date=new Date(f.downloaded_at*1000);label='Downloaded';}
  else if(f.created){date=new Date(f.created*1000);label='File created';}
  else return 'Date unknown';
  return Number.isNaN(date.getTime())?'Date unknown':`${label} ${date.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})}`;
}
let masterVolume=Math.max(0,Math.min(1,Number(localStorage.getItem('lv-volume')??'0.7'))),masterMuted=localStorage.getItem('lv-muted')==='true';
function applyVolume(){document.querySelectorAll('video').forEach(v=>{v.volume=masterVolume;v.muted=masterMuted;});$('master-volume').value=Math.round(masterVolume*100);$('master-mute').textContent=masterMuted||masterVolume===0?'🔇':'🔊';$('master-mute').setAttribute('aria-label',masterMuted?'Unmute all videos':'Mute all videos');}
