function contextFor(target,x,y){const tile=target.closest('[data-profile]');if(tile){const p=profileById(tile.dataset.profile);if(p){openAccountMenu(p,x,y,tile);return true;}}const category=target.closest('[data-tag]');if(category&&(current.type==='home'||current.type==='sources')){openCategoryMenu(category.dataset.tag,current.type==='sources'?'source':'destination',x,y,category);return true;}return false;}
document.addEventListener('contextmenu',e=>{if(contextFor(e.target,e.clientX,e.clientY))e.preventDefault();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!contextMenu.hidden){e.preventDefault();closeContextMenu(true);return;}if(!contextMenu.hidden&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const buttons=[...contextMenu.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();return;}if((e.key==='ContextMenu'||(e.shiftKey&&e.key==='F10'))&&document.activeElement){const rect=document.activeElement.getBoundingClientRect();if(contextFor(document.activeElement,rect.left,rect.bottom))e.preventDefault();}});
document.addEventListener('pointerdown',e=>{if(!contextMenu.hidden&&!contextMenu.contains(e.target))closeContextMenu();});window.addEventListener('resize',()=>closeContextMenu());
function openRemoveAccount(p){removingAccount=p;$('remove-account-title').textContent=`Remove ${isSolo(p)?'Solo Posts':'@'+p.name}?`;$('remove-account-description').textContent=`This ${p.role==='source'?'source':'profile'} will be hidden from your workspace and Sync all.`;$('remove-account-error').textContent='';$('remove-account-dialog').showModal();}
$('confirm-remove-account').onclick=async e=>{const b=e.currentTarget,p=removingAccount;b.disabled=true;$('remove-account-error').textContent='';try{await api(`/api/profiles/${p.id}/archive`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({archived:true})});$('remove-account-dialog').close();if(['profile','source'].includes(current.type)&&current.value===p.id)go(p.role==='source'?'sources':'home',null,p.role);await refresh();$('notice').textContent=`${isSolo(p)?'Solo Posts':'@'+p.name} removed from workspace. You can restore it from Removed accounts.`;}catch(err){$('remove-account-error').textContent=err.message;}finally{b.disabled=false;}};
async function openRemovedAccounts(role){$('removed-accounts-title').textContent=role==='source'?'Removed sources':'Removed profiles';$('removed-accounts-error').textContent='';$('removed-accounts-list').textContent='Loading…';$('removed-accounts-dialog').showModal();await loadRemovedAccounts(role);}
async function loadRemovedAccounts(role){try{const accounts=(await api('/api/profiles/hidden')).filter(p=>p.role===role);const list=$('removed-accounts-list');list.innerHTML=accounts.map(p=>`<div class="removed-account">${avatar(p)}<span><strong>${isSolo(p)?'Solo Posts':'@'+esc(p.name)}</strong><small>${esc(platformLabel(p.platform))}</small></span><button type="button" class="button outline" data-restore="${p.id}">Restore</button></div>`).join('')||'<p>No removed accounts in this section.</p>';list.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api(`/api/profiles/${b.dataset.restore}/archive`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({archived:false})});await refresh();$('notice').textContent='Account restored. Auto sync and Brave refresh remain off.';await loadRemovedAccounts(role);}catch(err){$('removed-accounts-error').textContent=err.message;b.disabled=false;}});}catch(err){$('removed-accounts-error').textContent=err.message;}}
let sourceSelection=null,selectionScrollTimer=null;
async function openSourceSelection(id){
 sourceSelection={id,preview:null};$('selection-content').hidden=true;$('selection-error').textContent='';$('selection-status').textContent='Loading post previews…';$('selection-start').disabled=true;$('selection-all-fallback').hidden=true;$('selection-title').textContent=`Choose posts from @${profileById(id)?.name||'source'}`;$('source-selection-dialog').showModal();
 try {const response=await api(`/api/sources/${id}/preview`,{method:'POST'});if(!sourceSelection||sourceSelection.id!==id)return;sourceSelection.preview=response.preview;const posts=response.preview.posts;$('selection-status').textContent=`${posts.length} posts found`;$('selection-reel').innerHTML=posts.map((p,i)=>`<button type="button" class="selection-post" data-index="${i}" title="${esc(p.title||p.id)}"><div class="selection-thumb">${p.thumbnail?`<img src="${esc(p.thumbnail)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="selection-missing" hidden>No preview</span>`:'<span class="selection-missing">No preview</span>'}</div><small>${esc(p.date||'Date unavailable')}</small><strong>${esc(p.title||p.id)}</strong><span class="selection-post-state"></span></button>`).join('');$('selection-slider').max=posts.length-1;$('selection-slider').value=0;$('selection-content').hidden=false;$('selection-start').disabled=false;document.querySelectorAll('input[name="selection-mode"]')[0].checked=true;
 const reel=$('selection-reel');clearTimeout(selectionScrollTimer);reel.scrollLeft=0;function select(index,move=true){index=Math.max(0,Math.min(posts.length-1,index));$('selection-slider').value=index;const mode=document.querySelector('input[name="selection-mode"]:checked').value;let count=0;reel.querySelectorAll('.selection-post').forEach((el,i)=>{const included=mode==='all'||(mode==='after'?i<=index:i>=index);if(included)count++;el.classList.toggle('selected',i===index);el.classList.toggle('excluded',!included);el.setAttribute('aria-pressed',String(i===index));el.querySelector('.selection-post-state').textContent=i===index?'CUTOFF · INCLUDED':included?'INCLUDED':'SKIPPED';});$('selection-current').textContent=`Cutoff: ${posts[index].title||posts[index].id}${posts[index].date?' · '+posts[index].date:''} (${index+1} of ${posts.length})`;$('selection-summary').textContent=`${count} selected to download · ${posts.length-count} skipped`;if(move)reel.children[index]?.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'});}
 $('selection-slider').oninput=e=>select(Number(e.target.value));document.querySelectorAll('input[name="selection-mode"]').forEach(el=>el.onchange=()=>select(Number($('selection-slider').value),false));reel.querySelectorAll('.selection-post').forEach(el=>el.onclick=()=>select(Number(el.dataset.index)));reel.onscroll=()=>{clearTimeout(selectionScrollTimer);selectionScrollTimer=setTimeout(()=>{const mid=reel.scrollLeft+reel.clientWidth/2;let best=0,dist=Infinity;Array.from(reel.children).forEach((el,i)=>{const d=Math.abs(el.offsetLeft+el.offsetWidth/2-mid);if(d<dist){dist=d;best=i;}});select(best,false);},80);};select(0,false);
 }catch(err){$('selection-status').textContent='Could not load previews.';$('selection-error').textContent=err.message;$('selection-all-fallback').hidden=false;}
}
async function saveSourceSelection(fallback){const button=fallback?$('selection-all-fallback'):$('selection-start');button.disabled=true;$('selection-error').textContent='';try{const id=sourceSelection.id,mode=fallback?'all':document.querySelector('input[name="selection-mode"]:checked').value;const chosen=await api(`/api/sources/${id}/selection`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:fallback?'':sourceSelection.preview.token,mode,cutoff:Number($('selection-slider').value)})});$('source-selection-dialog').close();await refresh();go('source',id);try{await api(`/api/sources/${id}/sync`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({include_photos:false})});await loadSource(id);if($('source-message'))$('source-message').textContent=`Selection saved: ${chosen.selected??'all'} selected, ${chosen.excluded} skipped.`;}catch(err){if($('source-message'))$('source-message').textContent=`Selection saved. Start sync when ready: ${err.message}`;}}catch(err){$('selection-error').textContent=err.message;}finally{button.disabled=false;}}
