$('solo-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$('solo-error').textContent='';try{const links=$('solo-links').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const result=await api('/api/solo-posts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({links})});$('solo-dialog').close();await refresh();go('source',result.id);}catch(err){$('solo-error').textContent=err.message;}finally{button.disabled=false;}};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
function identifyProfile(value){try{const u=new URL(value.trim()),host=u.hostname.toLowerCase(),bits=u.pathname.split('/').filter(Boolean);if(u.protocol!=='https:'||u.username||u.password)return null;const domain=d=>host===d||host.endsWith('.'+d);let platform='other',name='';if(domain('tiktok.com')){platform='tiktok';if(bits.length===1&&/^@[A-Za-z0-9._]+$/.test(bits[0]))name=bits[0].slice(1);}else if(domain('instagram.com')){platform='instagram';if(bits.length===1&&/^[A-Za-z0-9._]+$/.test(bits[0])&&!['p','reel','reels','stories','explore','accounts'].includes(bits[0].toLowerCase()))name=bits[0];}else if(domain('youtube.com')){platform='youtube';if(bits.length===1&&/^@[A-Za-z0-9._-]+$/.test(bits[0]))name=bits[0].slice(1);else if(bits.length===2&&['channel','c','user'].includes(bits[0])&&/^[A-Za-z0-9._-]+$/.test(bits[1]))name=bits[1];}return {platform,name};}catch{return null;}}
function detectProfile(){if(editingProfile)return;const result=identifyProfile($('profile-url').value);if(result?.name){$('profile-name').value=result.name;$('profile-platform').value=result.platform;$('profile-detected').textContent=`${platformLabel(result.platform)} · @${result.name} detected. Add a picture or category under More options.`;}else if($('profile-url').value.trim()){ $('profile-name').value='';$('profile-platform').value=result?.platform||'other';$('profile-detected').textContent='Account not recognized. Open More options to enter the name.';}else {$('profile-name').value='';$('profile-detected').textContent='TikTok, Instagram and YouTube account links are recognized automatically.';}}
$('profile-url').oninput=detectProfile;$('profile-url').onblur=()=>{if(!editingProfile&&$('profile-url').value.trim()&&!$('profile-name').value.trim())$('profile-options').open=true;};
$('profile-form').onsubmit=async e=>{e.preventDefault();if(!$('profile-name').value.trim()){$('profile-options').open=true;$('profile-error').textContent='Enter a name under More options.';return;}const newSource=!editingProfile&&$('profile-role').value==='source';const body={setup_selection:!editingProfile&&$('profile-role').value==='source',url:$('profile-url').value.trim(),name:$('profile-name').value.trim(),platform:$('profile-platform').value,role:$('profile-role').value,source_folder:$('source-folder').value.trim(),tags:$('profile-tags').value.split(',').map(x=>x.trim()).filter(Boolean)};const button=e.submitter;button.disabled=true;try{const result=await api(editingProfile?`/api/profiles/${editingProfile}`:'/api/profiles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const id=editingProfile||result.id;const photo=$('profile-photo').files[0];let warning='';if(photo){const form=new FormData();form.append('photo',photo);try{await api(`/api/profiles/${id}/photo`,{method:'POST',body:form});}catch(err){warning=` Source saved, but the picture could not be added: ${err.message}`;}}$('profile-dialog').close();await refresh();if(current.type==='source')await loadSource(current.value);$('notice').textContent=warning|| (editingProfile?'Saved.':'Added.');if(newSource)openSourceSelection(id);}catch(err){$('profile-error').textContent=err.message;}finally{button.disabled=false;}};
