let analyticsChart=null;
async function loadAnalytics(id){
  const host=$('profile-analytics');if(!host)return;
  try{
    const [records,bridgeConfig]=await Promise.all([api(`/api/profiles/${id}/analytics`),api(`/api/profiles/${id}/analytics-bridge`).catch(()=>null)]);if(current.type!=='profile'||current.value!==id||!$('profile-analytics'))return;
    const account=records.filter(r=>!r.post_id),posts=new Map();for(const r of records)if(r.post_id&&!posts.has(r.post_id))posts.set(r.post_id,r);
    const metrics=['followers','following','views','likes','comments','shares'];
    const metricCard=key=>{const samples=account.filter(r=>r[key]!==null&&r[key]!==undefined),latest=samples[0],previous=samples.find(r=>r.date<latest?.date),change=latest&&previous&&!latest.approx?.includes(key)&&!previous.approx?.includes(key)?latest[key]-previous[key]:null;return `<div><small>${esc(key.toUpperCase())}</small><strong>${latest?(latest.approx?.includes(key)?'≈':'')+Number(latest[key]).toLocaleString():'—'}</strong><span>${latest?`${esc(latest.source)} · ${esc(latest.date)}${change===null?'':` · ${change>=0?'+':''}${change.toLocaleString()} since ${esc(previous.date)}`}`:'No data yet'}</span></div>`;};
    const top=[...posts.values()].sort((a,b)=>(b.views??-1)-(a.views??-1)).slice(0,10);
    host.innerHTML=`<div class="section-heading analytics-heading"><div><div class="eyebrow">YOUR PERFORMANCE</div><h2>Analytics</h2><p>Saved locally · public profile counts can refresh through Brave.</p></div><div class="analytics-actions">${bridgeConfig?'<button class="button outline" id="analytics-bridge">⚙ Brave refresh</button><button class="button outline" id="analytics-refresh">↻ Refresh counts</button>':''}<button class="button ghost" id="analytics-template">CSV template</button><label class="button outline analytics-import">Import CSV<input id="analytics-csv" type="file" accept=".csv,text/csv" hidden></label><button class="button primary" id="analytics-add">＋ Record numbers</button></div></div><div id="analytics-message" role="status"></div><div class="dashboard-stats analytics-stats">${metrics.map(metricCard).join('')}</div><div class="analytics-panels"><div class="analytics-panel"><div class="analytics-panel-head"><h3>Account trend</h3><select id="analytics-metric" aria-label="Trend metric">${metrics.map(m=>`<option value="${m}">${m[0].toUpperCase()+m.slice(1)}</option>`).join('')}</select></div><div class="analytics-chart"><canvas id="analytics-chart" aria-label="Account metric trend" role="img"></canvas><p id="analytics-chart-empty">Record at least one account snapshot to see a trend.</p></div></div><div class="analytics-panel"><h3>Post performance</h3>${top.length?`<div class="analytics-table-wrap"><table class="analytics-table"><thead><tr><th>Post ID</th><th>Views</th><th>Likes</th><th>As of</th></tr></thead><tbody>${top.map(r=>`<tr><td>${esc(r.post_id)}</td><td>${r.views==null?'—':Number(r.views).toLocaleString()}</td><td>${r.likes==null?'—':Number(r.likes).toLocaleString()}</td><td>${esc(r.date)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No post metrics yet. Add a post ID when recording numbers or importing CSV.</p>'}</div></div><p class="analytics-note">${bridgeConfig?.enabled?`Brave refresh is on.${bridgeConfig.last_success?` Last success: ${esc(new Date(bridgeConfig.last_success*1000).toLocaleString())}.`: ' Waiting for the extension.'}${bridgeConfig.last_error?` ${esc(bridgeConfig.last_error)}`:''}`:'Brave refresh is off.'} ≈ means a rounded platform count. Private platform insights are not included.</p>`;
    if(bridgeConfig){$('analytics-bridge').onclick=()=>openBridgeSettings(id);$('analytics-refresh').onclick=async()=>{try{await api(`/api/profiles/${id}/analytics-bridge/refresh`,{method:'POST'});$('analytics-message').textContent='Refresh requested. Brave will check within about a minute while both apps are open.';}catch(err){$('analytics-message').textContent=err.message;}};}
    $('analytics-add').onclick=()=>{const f=$('analytics-form');f.reset();const now=new Date();f.elements.date.value=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');$('analytics-error').textContent='';$('analytics-dialog').showModal();};
    $('analytics-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,body={date:f.elements.date.value,post_id:f.elements.post_id.value.trim()};for(const k of metrics)body[k]=f.elements[k].value===''?null:Number(f.elements[k].value);const button=e.submitter;button.disabled=true;try{await api(`/api/profiles/${id}/analytics`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('analytics-dialog').close();await loadAnalytics(id);}catch(err){$('analytics-error').textContent=err.message;}finally{button.disabled=false;}};
    $('analytics-template').onclick=()=>{const blob=new Blob(['date,post_id,followers,following,views,likes,comments,shares\r\n2026-11-18,,100,20,,,,\r\n2026-11-18,example-post,,,500,30,4,2\r\n'],{type:'text/csv'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='lifeinvader-analytics-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
    $('analytics-csv').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('CSV must be 2 MB or smaller.');const result=await api(`/api/profiles/${id}/analytics/import`,{method:'POST',headers:{'Content-Type':'text/csv'},body:await file.text()});await loadAnalytics(id);if($('analytics-message'))$('analytics-message').textContent=`Imported ${result.imported} rows.`;}catch(err){$('analytics-message').textContent=err.message;}finally{e.target.value='';}};
    function draw(){const key=$('analytics-metric').value,points=account.filter(r=>r[key]!=null).slice().reverse();$('analytics-chart-empty').hidden=points.length>0;if(analyticsChart)analyticsChart.destroy();analyticsChart=null;if(points.length&&window.Chart){analyticsChart=new Chart($('analytics-chart'),{type:'line',data:{labels:points.map(r=>r.date),datasets:[{label:key,data:points.map(r=>r[key]),borderColor:'#ec65a4',backgroundColor:'rgba(236,101,164,.15)',tension:.2,pointRadius:3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:false}}}});}}
    $('analytics-metric').onchange=draw;draw();
  }catch(err){if(current.type==='profile'&&current.value===id&&$('profile-analytics'))$('profile-analytics').innerHTML=`<p class="form-error">Analytics could not load: ${esc(err.message)}</p>`;}
}
let queueData=[],pickedSource=null,queueEdit=null;
async function loadQueue(id){
 try{const entries=await api(`/api/profiles/${id}/queue`);if(current.type!=='profile'||current.value!==id||!$('posting-queue'))return;queueData=entries;const active=entries.filter(x=>x.state==='queued'),history=entries.filter(x=>x.state!=='queued');
  const card=q=>`<article class="queue-card"><div class="queue-meta"><strong>${esc(q.title||q.post_id||q.path.split('/').pop())}</strong><small>${esc(platformLabel(q.platform))} · @${esc(q.source_name)} · ${q.posted_date?(q.posted_date_kind==='estimated_id'?'Estimated post date (UTC) ':'Originally posted ')+esc(q.posted_date):'Original date unknown'}${q.scheduled_for?' · Planned '+esc(q.scheduled_for.replace('T',' ')):''}</small>${q.description?`<p>${esc(q.description)}</p>`:''}${q.edited_path?'<small>Edited copy · ready for review</small>':''}${!q.available?'<small class="form-error">Queue file unavailable. Check the selected source folder.</small>':''}</div><div class="queue-actions">${q.available?`<a class="button ghost" href="/api/sources/${q.source_id}/file?path=${encodeURIComponent(q.edited_path||q.path)}" target="_blank">Open file</a>`:''}${safeUrl(q.channel_url)?`<a class="button ghost" href="${esc(safeUrl(q.channel_url))}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:''}${safeUrl(q.original_url)?`<a class="button ghost" href="${esc(safeUrl(q.original_url))}" target="_blank" rel="noopener noreferrer">Original post ↗</a>`:''}<button class="button ghost" data-copy="${q.id}">Copy text</button><button class="button outline" data-queue-edit="${q.id}">${q.state==='queued'?'Update status':esc(q.state)}</button></div></article>`;
  $('posting-queue').innerHTML=`<div class="section-heading"><div><div class="eyebrow">YOUR NEXT POSTS</div><h2>Posting queue <small>${active.length}</small></h2><p>Items stay here until you record their status. Planned times do not post automatically.</p></div><div class="queue-heading-actions"><button class="button outline" id="queue-copy-handoff">Copy AI handoff</button><button class="button outline" id="queue-save-handoff">Download handoff</button><button class="button primary" id="queue-pick">✳ Pick from sources</button></div></div><div id="queue-message" role="status"></div>${active.length?active.map(card).join(''):'<div class="queue-empty">Your queue is empty. Pick downloaded media from your sources.</div>'}${history.length?`<details class="queue-history"><summary>Recorded posts (${history.length})</summary>${history.map(card).join('')}</details>`:''}`;
  async function handoff(){return JSON.stringify(await api('/api/posting-handoff'),null,2);}
  $('queue-copy-handoff').onclick=async()=>{try{await navigator.clipboard.writeText(await handoff());$('queue-message').textContent='AI handoff copied. It includes local paths and queue details for all profiles.';}catch(err){$('queue-message').textContent=`Could not copy the handoff: ${err.message}`;}};
  $('queue-save-handoff').onclick=async()=>{try{const url=URL.createObjectURL(new Blob([await handoff()],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='lifeinvader-posting-handoff.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('queue-message').textContent='Handoff downloaded. It contains private local paths and queue details.';}catch(err){$('queue-message').textContent=`Could not download the handoff: ${err.message}`;}};
  $('queue-pick').onclick=()=>openPicker(id);$('posting-queue').querySelectorAll('[data-copy]').forEach(button=>button.onclick=async()=>{const q=entries.find(x=>x.id===Number(button.dataset.copy));try{await navigator.clipboard.writeText([q.title,q.description,q.original_url,q.channel_url].filter(Boolean).join('\n\n'));$('queue-message').textContent='Source details copied.';}catch{$('queue-message').textContent='Clipboard unavailable. Select and copy the text instead.';}});
  $('posting-queue').querySelectorAll('[data-queue-edit]').forEach(button=>button.onclick=()=>{const q=entries.find(x=>x.id===Number(button.dataset.queueEdit));queueEdit=q;$('queue-state').value=q.state;$('queue-caption').value=q.caption;$('queue-post-url').value=q.post_url;$('queue-scheduled').value=q.scheduled_for;$('queue-note').value='';$('queue-note-kind').value='note';$('queue-activity').textContent='Loading activity…';$('queue-error').textContent='';$('queue-dialog').showModal();api(`/api/profiles/${id}/queue/${q.id}/events`).then(events=>{if(queueEdit?.id!==q.id)return;$('queue-activity').innerHTML=events.length?events.map(e=>`<div class="queue-event"><strong>${esc(e.event_type.replaceAll('_',' '))}</strong> · ${esc(e.recorded_at_utc)} · ${esc(e.state)}${e.note?`<p>${esc(e.note)}</p>`:''}${e.post_url?`<p>${esc(e.post_url)}</p>`:''}</div>`).join(''):'<p>No activity was recorded before logging was added.</p>';}).catch(err=>{$('queue-activity').textContent=`Could not load activity: ${err.message}`;});});
  $('queue-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api(`/api/profiles/${id}/queue/${queueEdit.id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:$('queue-state').value,caption:$('queue-caption').value,post_url:$('queue-post-url').value.trim(),scheduled_for:$('queue-scheduled').value,note:$('queue-note').value,note_kind:$('queue-note-kind').value,expected_revision:queueEdit.revision})});$('queue-dialog').close();await loadQueue(id);}catch(err){$('queue-error').textContent=err.message;}finally{button.disabled=false;}};
 }catch(e){if(current.type==='profile'&&current.value===id&&$('posting-queue'))$('posting-queue').innerHTML=`<p class="form-error">Queue could not load: ${esc(e.message)}</p>`;}
}
function openPicker(id){
 const sources=data.profiles.filter(p=>p.role==='source');let seenPicks=new Set();$('picker-form').reset();$('picker-category').innerHTML='<option value="">All categories</option>'+allTags('source').map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');$('picker-source').innerHTML='<option value="">All sources</option>'+sources.map(p=>`<option value="${p.id}">${esc(platformLabel(p.platform))} · @${esc(p.name)}</option>`).join('');$('picker-result').textContent='Choose filters, then pick a post.';$('picker-error').textContent='';$('picker-queue').disabled=true;pickedSource=null;$('picker-dialog').showModal();document.querySelectorAll('#picker-category,#picker-source,#picker-type,#picker-order,#picker-min,#picker-max,#picker-from,#picker-to,#picker-search,#picker-unknown,#picker-estimated').forEach(el=>el.onchange=()=>{seenPicks.clear();pickedSource=null;$('picker-queue').disabled=true;});
 $('picker-random').onclick=async()=>{const button=$('picker-random');button.disabled=true;$('picker-error').textContent='';$('picker-result').textContent='Looking through downloaded posts…';try{const category=$('picker-category').value,selected=$('picker-source').value,from=$('picker-from').value,to=$('picker-to').value,query=$('picker-search').value.trim().toLowerCase(),unknown=$('picker-unknown').checked,includeEstimates=$('picker-estimated').checked,type=$('picker-type').value,order=$('picker-order').value,min=$('picker-min').value,max=$('picker-max').value;if(min&&max&&Number(min)>Number(max))throw new Error('Minimum length cannot exceed maximum length.');if(from&&to&&from>to)throw new Error('The start date must be before the end date.');const group=sources.filter(p=>(!selected||p.id===Number(selected))&&(!category||hasTag(p,category)));const results=await Promise.all(group.map(async p=>{try{const r=await api(`/api/sources/${p.id}`);return {p,files:(r.files||[]).map(f=>({...f,_libraryRoot:r.root})),configured:r.configured};}catch{return {p,files:[],error:true};}}));let candidates=[];for(const {p,files} of results)for(const f of files){const seconds=LVLibrary.durationFor(p,f);if(type&&f.kind!==type)continue;if((min||max)&&(f.kind!=='video'||seconds==null||(min&&seconds<Number(min))||(max&&seconds>Number(max))))continue;const date=f.posted_date||'';if(!includeEstimates&&f.posted_date_kind==='estimated_id')continue;if((from||to)&&!date&&!unknown)continue;if(date&&((from&&date<from)||(to&&date>to)))continue;if(query&&!`${f.title||f.name} ${f.description||''}`.toLowerCase().includes(query))continue;if(queueData.some(q=>q.platform===p.platform&&(f.post_id?q.post_id===f.post_id:q.source_id===p.id&&q.path===f.path)))continue;candidates.push({p,f});}const unique=new Map();for(const c of candidates){const key=c.f.kind==='image'?`${c.p.id}:${c.f.path}`:c.f.post_id?`${c.p.platform}:${c.f.post_id}`:`${c.p.id}:${c.f.path}`;if(!unique.has(key))unique.set(key,c);}candidates=[...unique.values()];if(!candidates.length){pickedSource=null;$('picker-queue').disabled=true;$('picker-result').textContent='No eligible downloaded media matches. Check source folders, filters and recorded posts.';if(results.some(r=>r.error||!r.configured))$('picker-error').textContent='Some sources could not be opened.';return;}const keyFor=c=>c.f.kind==='image'?`${c.p.id}:${c.f.path}`:c.f.post_id?`${c.p.platform}:${c.f.post_id}`:`${c.p.id}:${c.f.path}`;let unseen=candidates.filter(c=>!seenPicks.has(keyFor(c)));if(!unseen.length){seenPicks.clear();unseen=candidates;}if(order==='shuffle'){const random=new Uint32Array(1);crypto.getRandomValues(random);pickedSource=unseen[random[0]%unseen.length];}else{unseen.sort((a,b)=>order==='newest'?(b.f.posted_date||'').localeCompare(a.f.posted_date||''):order==='oldest'?(a.f.posted_date||'9999').localeCompare(b.f.posted_date||'9999'):order==='shortest'?(LVLibrary.durationFor(a.p,a.f)??Infinity)-(LVLibrary.durationFor(b.p,b.f)??Infinity):(LVLibrary.durationFor(b.p,b.f)??-1)-(LVLibrary.durationFor(a.p,a.f)??-1));pickedSource=unseen[0];}seenPicks.add(keyFor(pickedSource));const {p,f}=pickedSource;$('picker-result').innerHTML=`<strong>${esc(f.title||f.name)}</strong><p>@${esc(p.name)} · ${f.posted_date?(f.posted_date_kind==='estimated_id'?'Estimated post date (UTC) ':'Originally posted ')+esc(f.posted_date):'Original date unknown'} · ${f.kind==='video'?'Video':'Photo'}${LVLibrary.durationFor(p,f)!=null?' · '+Math.round(LVLibrary.durationFor(p,f))+' sec':''}</p>${f.description?`<p>${esc(f.description)}</p>`:''}<small>${candidates.length} matching posts</small>`;$('picker-queue').disabled=false;if(results.some(r=>r.error||!r.configured))$('picker-error').textContent='Some sources could not be opened.';}catch(e){$('picker-error').textContent=e.message;}finally{button.disabled=false;}};
 $('picker-form').onsubmit=async e=>{e.preventDefault();if(!pickedSource)return;const button=e.submitter;button.disabled=true;try{await api(`/api/profiles/${id}/queue`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_id:pickedSource.p.id,path:pickedSource.f.path,scheduled_for:$('picker-scheduled').value})});$('picker-dialog').close();await loadQueue(id);}catch(err){$('picker-error').textContent=err.message;button.disabled=false;}};
}

async function openBridgeSettings(id){try{const [config,pairing]=await Promise.all([api(`/api/profiles/${id}/analytics-bridge`),api('/api/bridge/pair')]);$('bridge-code').value=pairing.token;$('bridge-code').type='password';$('bridge-enabled').checked=config.enabled;$('bridge-after-post').checked=config.after_post;$('bridge-interval').value=String(config.interval_seconds);$('bridge-state').textContent=config.last_error||'';$('bridge-error').textContent='';$('bridge-dialog').showModal();$('bridge-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('bridge-code').value);$('bridge-state').textContent='Pairing code copied.';}catch{$('bridge-code').type='text';$('bridge-code').select();$('bridge-state').textContent='Copy the selected code.';}};$('bridge-revoke').onclick=async()=>{try{await api('/api/bridge/pair',{method:'DELETE'});const next=await api('/api/bridge/pair');$('bridge-code').value=next.token;$('bridge-state').textContent='Old code revoked. Reconnect your browser with this new code.';}catch(err){$('bridge-error').textContent=err.message;}};$('bridge-form').onsubmit=async e=>{e.preventDefault();try{await api(`/api/profiles/${id}/analytics-bridge`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:$('bridge-enabled').checked,interval_seconds:Number($('bridge-interval').value),after_post:$('bridge-after-post').checked})});$('bridge-dialog').close();if(current.type==='profile'&&current.value===id)await loadAnalytics(id);else if(current.type==='source'&&current.value===id)await loadSource(id);}catch(err){$('bridge-error').textContent=err.message;}};}catch(err){$('notice').textContent=err.message;}}

// Update the visible dashboard after an extension refresh, without interrupting an open dialog.
setInterval(()=>{if(current.type==='profile'&&!document.hidden&&!document.querySelector('dialog[open]')&&!document.activeElement?.closest('#profile-analytics button, #profile-analytics select, #profile-analytics input'))loadAnalytics(current.value);},20000);

let auditSelection=[],auditSelectionLabel="",auditPollTimer=null,auditWasRunning=false;
async function refreshDateAudit(){try{const {run}=await api('/api/date-audit');const running=run?.state==='running';$('date-audit-scope').textContent=running?'An audit is in progress. Showing its status.':auditSelectionLabel;$('date-audit-online').disabled=!!running;if(running)$('date-audit-online').checked=!!run.online;$('date-audit-start').disabled=!!running;$('date-audit-cancel').hidden=!running;$('date-audit-cancel').disabled=!!run?.cancel_requested;$('date-audit-progress').hidden=!run;$('date-audit-progress').value=run?.total?Math.min(100,100*run.processed/run.total):0;$('date-audit-status').textContent=run?`${run.message} ${run.processed}/${run.total} files · ${run.verified} platform/metadata dates · ${run.estimated} estimates · ${run.unknown} unknown${run.online?` · ${run.failed} online checks failed`:''}`:'No audit has been run yet.';if(auditWasRunning&&!running){if(current.type==='source')loadSource(current.value);clearInterval(auditPollTimer);auditPollTimer=null;}auditWasRunning=!!running;return run;}catch(e){$('date-audit-error').textContent=e.message;}}
function openDateAudit(ids,label){auditSelection=ids;auditSelectionLabel=`Selected: ${label} · ${ids.length} ${ids.length===1?'source':'sources'}`;$('date-audit-scope').textContent=auditSelectionLabel;$('date-audit-online').checked=false;$('date-audit-error').textContent='';$('date-audit-dialog').showModal();refreshDateAudit();if(!auditPollTimer)auditPollTimer=setInterval(refreshDateAudit,1500);}
$('date-audit-form').onsubmit=async e=>{e.preventDefault();$('date-audit-error').textContent='';try{await api('/api/date-audit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile_ids:auditSelection,online:$('date-audit-online').checked})});auditWasRunning=true;await refreshDateAudit();if(!auditPollTimer)auditPollTimer=setInterval(refreshDateAudit,1500);}catch(err){$('date-audit-error').textContent=err.message;}};
$('date-audit-cancel').onclick=async()=>{try{await api('/api/date-audit/cancel',{method:'POST'});await refreshDateAudit();}catch(err){$('date-audit-error').textContent=err.message;}};
$('date-audit-dialog').addEventListener('close',()=>{clearInterval(auditPollTimer);auditPollTimer=null;});
